import { Claims } from '../claims/claims';
import { Periods } from '../periods/periods';
import { Rates } from '../rates/rates';

// The active sheet's people: listed in the order they were added, added and edited through one form,
// each with their claims, what they have claimed and what is due (the sum of their claims' due
// figures), and the sheet's claimed-total and due-total. The sheet's rates are set here too.
@Component({
  selector: 'app-people',
  imports: [Claims, Periods, Rates],
  template: `
    <app-rates [rates]="rates()" [today]="today()" (saved)="rateSaved($event)" />
    <app-periods
      [periods]="periods()"
      [dueTotals]="periodDueTotals()"
      (saved)="periodSaved($event)"
      (closed)="periodClosed($event)"
    />
    <section aria-labelledby="people-heading">
      <h2 id="people-heading">People</h2>
      <form (submit)="save($event)" [attr.aria-label]="editing() === null ? 'Add a person' : 'Edit a person'">
        <label for="person-form-name">Name</label>
        <input
          id="person-form-name"
          data-testid="person-form-name"
          [value]="name()"
          (input)="name.set(value($event)); error.set(null)"
        />
        <label for="person-form-grade">Grade</label>
        <select
          id="person-form-grade"
          data-testid="person-form-grade"
          [value]="grade()"
          (change)="grade.set(gradeOf($event)); error.set(null)"
        >
          @for (g of grades; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <button type="submit" data-testid="person-form-submit">
          {{ editing() === null ? 'Add person' : 'Save person' }}
        </button>
        @if (editing() !== null) {
          <button type="button" data-testid="person-form-cancel" (click)="reset()">Cancel</button>
        }
        @if (error(); as message) {
          <p role="alert" data-testid="person-form-error">{{ message }}</p>
        }
      </form>
      <p>Claimed in total <strong data-testid="rollup-claimed-total">{{ claimedTotal() }}</strong></p>
      <p>Due in total <strong data-testid="rollup-due-total">{{ dueTotal() }}</strong></p>
      <table>
        <thead>
          <tr>
            <th scope="col">Name</th>
            <th scope="col">Grade</th>
            <th scope="col">Claimed</th>
            <th scope="col">Due</th>
            <th scope="col">Statements</th>
            <th scope="col">Claims</th>
            <th scope="col"><span class="visually-hidden">Actions</span></th>
          </tr>
        </thead>
        <tbody>
          @for (p of people(); track p.id) {
            <tr [attr.data-testid]="'person-row-' + p.id">
              <td data-testid="person-name">{{ p.name }}</td>
              <td data-testid="person-grade">{{ p.grade }}</td>
              <td data-testid="person-claimed">{{ claimed(p.id) }}</td>
              <td data-testid="person-due-total">{{ dueTotalOf(p) }}</td>
              <td>
                <span data-testid="person-statement-count">{{ p.statementCount }}</span>
                <span>Last <span data-testid="person-stated-total">{{ statedTotalOf(p) }}</span></span>
                <span>on <span data-testid="person-statement-date">{{ p.statementDate ?? '' }}</span></span>
              </td>
              <td>
                <app-claims
                  [personId]="p.id"
                  [personName]="p.name"
                  [claims]="claimsOf(p.id)"
                  [grade]="p.grade"
                  [rates]="rates()"
                  [periods]="periods()"
                  (saved)="claimSaved($event)"
                />
              </td>
              <td>
                <button
                  type="button"
                  [attr.data-testid]="'person-edit-' + p.id"
                  [attr.aria-label]="'Edit ' + p.name"
                  (click)="open(p)"
                >
                  Edit
                </button>
                <button
                  type="button"
                  data-testid="person-statement"
                  [attr.aria-label]="'Take a statement for ' + p.name"
                  (click)="statement(p)"
                >
                  Statement
                </button>
                @if (personError()?.id === p.id) {
                  <p role="alert" data-testid="person-error">{{ personError()?.message }}</p>
                }
              </td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class People {
  private readonly session = inject(Session);
  private readonly api = inject(PeopleApi);
  private readonly claimsApi = inject(ClaimsApi);
  private readonly ratesApi = inject(RatesApi);
  private readonly periodsApi = inject(PeriodsApi);

  protected readonly grades = GRADES;
  protected readonly people = signal<PersonView[]>([]);
  /** The sheet's claims, newest first. */
  protected readonly claims = signal<ClaimView[]>([]);
  private readonly byPerson = computed(() => {
    const map = new Map<number, ClaimView[]>();
    for (const c of this.claims()) map.set(c.personId, [...(map.get(c.personId) ?? []), c]);
    return map;
  });
  /** The sheet's rates, each grade's by from-date; a grade with no rate is not listed. */
  protected readonly rates = signal<RateView[]>([]);
  /** The sheet's periods by from-date. */
  protected readonly periods = signal<PeriodView[]>([]);
  /**
   * Each period's due-total by period id: the sum of the due figures of the OPEN and SETTLED claims
   * dated in it, each at its own person's grade (a claim with no figure adds nothing).
   */
  protected readonly periodDueTotals = computed(() => {
    const totals = new Map<number, number>(this.periods().map((p) => [p.id, 0]));
    const grades = new Map(this.people().map((p) => [p.id, p.grade]));
    for (const c of this.claims().filter(counts)) {
      const period = periodOn(this.periods(), c.date);
      const grade = grades.get(c.personId);
      if (!period || !grade) continue;
      totals.set(period.id, totals.get(period.id)! + (claimDueCents(c, this.rates(), grade) ?? 0));
    }
    return new Map([...totals].map(([id, total]) => [id, money(total)]));
  });
  /** The sheet's today, on which each grade's rate in force is read. */
  protected readonly today = computed(() => this.session.today() ?? '');
  protected readonly claimedTotal = computed(() => money(this.claims().filter(counts).reduce((sum, c) => sum + cents(c.amount), 0)));
  /** Everyone's due-total added up, skipping those shown as n/a. */
  protected readonly dueTotal = computed(() =>
    money(
      this.people().reduce((sum, p) => sum + (this.dueTotalCents(p) ?? 0), 0),
    ),
  );
  protected readonly name = signal('');
  protected readonly grade = signal<Grade>('A');
  /** The id of the person open in the form, or null when the form adds a new person. */
  protected readonly editing = signal<number | null>(null);
  /** The version of the person open in the form, as it was loaded. */
  private readonly version = signal(0);
  protected readonly error = signal<string | null>(null);
  /** The refusal of the last action taken on a person's row, shown on that row. */
  protected readonly personError = signal<{ id: number; message: string } | null>(null);
  /** A submit is waiting for its answer: a second submit meanwhile is ignored. */
  private busy = false;

  constructor() {
    // Every sheet load re-reads the sheet's people from the store.
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loads();
      untracked(() => {
        this.people.set([]);
        this.claims.set([]);
        this.rates.set([]);
        this.periods.set([]);
        this.reset();
        this.personError.set(null);
        if (sheet) void this.reload(sheet);
      });
    });
  }

  protected claimsOf(personId: number): ClaimView[] {
    return this.byPerson().get(personId) ?? [];
  }

  /** What a person has claimed: the sum of their OPEN and SETTLED claims' amounts. */
  protected claimed(personId: number): string {
    return money(this.claimedCents(personId));
  }

  private claimedCents(personId: number): number {
    return this.claimsOf(personId).filter(counts).reduce((sum, c) => sum + cents(c.amount), 0);
  }

  /** The rate a grade has in force on the sheet's today (a two-decimal percent), or null when it has none. */
  protected pctOf(grade: Grade): string | null {
    return rateOn(this.rates(), grade, this.today());
  }

  /** A person's due-total: the sum of their counting claims' due figures, or n/a (see dueTotalCents). */
  protected dueTotalOf(person: PersonView): string {
    const total = this.dueTotalCents(person);
    return total === null ? NO_RATE : money(total);
  }

  /**
   * A person's due-total in whole cents: the sum of the due figures of their OPEN and SETTLED claims
   * (0 with none). Null (n/a) when their grade has no rate on the sheet's today, unless a settled
   * or stated claim keeps a fixed figure: then it is the sum of the figures there are.
   */
  private dueTotalCents(person: PersonView): number | null {
    const counting = this.claimsOf(person.id).filter(counts);
    const fixed = (c: ClaimView) => c.settledDue !== null || (c.stated && c.statedDue !== null);
    if (this.pctOf(person.grade) === null && !counting.some(fixed)) return null;
    return counting.reduce((sum, c) => sum + (claimDueCents(c, this.rates(), person.grade) ?? 0), 0);
  }

  /** The last statement's due-total: n/a when it was, empty when none was taken. */
  protected statedTotalOf(person: PersonView): string {
    if (person.statementCount === 0) return '';
    return person.statementTotal ?? NO_RATE;
  }

  /** Take a statement for a person: the row and their claims show what the store holds after it. */
  protected async statement(person: PersonView): Promise<void> {
    this.personError.set(null);
    const sheet = this.session.sheet();
    if (!sheet) return;
    try {
      const stated = await this.api.statement(sheet, person.id);
      if (this.session.sheet() !== sheet) return;
      this.people.update((list) => list.map((p) => (p.id === stated.person.id ? stated.person : p)));
      const byId = new Map(stated.claims.map((c) => [c.id, c]));
      this.claims.update((list) => list.map((c) => byId.get(c.id) ?? c));
    } catch {
      this.personError.set({ id: person.id, message: 'The statement could not be taken.' });
    }
  }

  /** A rate set for a grade, in place of any it had from the same date. */
  protected rateSaved(rate: RateView): void {
    this.rates.update((list) => [...list.filter((r) => !sameSlot(r, rate)), rate]);
  }

  /** A period added, kept in from-date order. */
  protected periodSaved(period: PeriodView): void {
    this.periods.update((list) => [...list, period].sort((a, b) => a.from.localeCompare(b.from)));
  }

  /** A period closed, in its place. */
  protected periodClosed(period: PeriodView): void {
    this.periods.update((list) => list.map((p) => (p.id === period.id ? period : p)));
  }

  /** A claim added (listed first, as the newest) or saved or moved (in its place). */
  protected claimSaved(claim: ClaimView): void {
    this.claims.update((list) =>
      list.some((c) => c.id === claim.id) ? list.map((c) => (c.id === claim.id ? claim : c)) : [claim, ...list],
    );
  }

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  protected gradeOf(event: Event): Grade {
    return (event.target as HTMLSelectElement).value as Grade;
  }

  /** Open a person's editor: the form takes their values. */
  protected open(person: PersonView): void {
    this.personError.set(null);
    this.editing.set(person.id);
    this.version.set(person.version);
    this.name.set(person.name);
    this.grade.set(person.grade);
    this.error.set(null);
  }

  protected reset(): void {
    this.editing.set(null);
    this.name.set('');
    this.grade.set('A');
    this.error.set(null);
  }

  protected async save(event: Event): Promise<void> {
    event.preventDefault();
    if (this.busy) return;
    this.error.set(null);
    const sheet = this.session.sheet();
    if (!sheet) return;
    const form = { name: this.name(), grade: this.grade() };
    if (!form.name.trim()) {
      this.error.set('Type a name for the person.');
      return;
    }
    const id = this.editing();
    this.busy = true;
    try {
      if (id === null) {
        const added = await this.api.add(sheet, form);
        this.people.update((list) => [...list, added]);
      } else {
        const saved = await this.api.edit(sheet, id, { ...form, version: this.version() });
        this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
      }
      this.reset();
    } catch (e) {
      if (id !== null && e instanceof HttpErrorResponse && e.status === 412) {
        await this.showCurrent(sheet, id);
        this.error.set('Someone else has saved this person since you opened it. The form shows their values now.');
      } else if (e instanceof HttpErrorResponse && e.status === 409) {
        this.error.set('That name is already in use on this sheet.');
      } else {
        this.error.set(id === null ? 'The person could not be added.' : 'The person could not be saved.');
      }
    } finally {
      this.busy = false;
    }
  }

  /** Someone else saved the person open in the form: show what the store holds for them now. */
  private async showCurrent(sheet: string, id: number): Promise<void> {
    try {
      const current = (await this.api.list(sheet)).find((p) => p.id === id);
      if (!current || this.session.sheet() !== sheet || this.editing() !== id) return;
      this.people.update((list) => list.map((p) => (p.id === id ? current : p)));
      this.version.set(current.version);
      this.name.set(current.name);
      this.grade.set(current.grade);
    } catch {
      // the form keeps what was typed; the refusal is still shown
    }
  }

  private async reload(sheet: string): Promise<void> {
    const loads = this.session.loads();
    const [people, claims, rates, periods] = await Promise.all([
      this.api.list(sheet),
      this.claimsApi.list(sheet),
      this.ratesApi.list(sheet),
      this.periodsApi.list(sheet),
    ]);
    // A later load may have started while this one was in flight: only the latest is shown.
    if (this.session.sheet() === sheet && this.session.loads() === loads) {
      this.claims.set(claims);
      this.rates.set(rates);
      this.periods.set(periods);
      this.people.set(people);
    }
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { ClaimView } from './claims';

export const GRADES = ['A', 'B', 'C'] as const;
export type Grade = (typeof GRADES)[number];

export interface PersonView {
  id: number;
  name: string;
  grade: Grade;
  /** Raised on every save of the person. */
  version: number;
  /** How many statements have been taken for the person. */
  statementCount: number;
  /** The last statement's due-total with two decimals; null when it was n/a, or none was taken. */
  statementTotal: string | null;
  /** The sheet's today (yyyy-mm-dd) when the last statement was taken; null when none was. */
  statementDate: string | null;
}

/** A statement taken: the person as stated and their claims, newest first. */
export interface StatementView {
  person: PersonView;
  claims: ClaimView[];
}

export interface PersonForm {
  name: string;
  grade: Grade;
  /** On an edit, the version of the person the form loaded. */
  version?: number;
}

// The people kept on a sheet, read from and written to the store.
@Injectable({ providedIn: 'root' })
export class PeopleApi {
  private readonly http = inject(HttpClient);

  /** The sheet's people in the order they were added. */
  list(sheet: string): Promise<PersonView[]> {
    return firstValueFrom(this.http.get<PersonView[]>(this.url(sheet)));
  }

  add(sheet: string, form: PersonForm): Promise<PersonView> {
    return firstValueFrom(this.http.post<PersonView>(this.url(sheet), form));
  }

  edit(sheet: string, id: number, form: PersonForm): Promise<PersonView> {
    return firstValueFrom(this.http.put<PersonView>(`${this.url(sheet)}/${id}`, form));
  }

  /** Take a statement: record the person's due-total and bind their counting claims to their figures. */
  statement(sheet: string, id: number): Promise<StatementView> {
    return firstValueFrom(this.http.post<StatementView>(`${this.url(sheet)}/${id}/statements`, null));
  }

  private url(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}/people`;
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';

/** DRAFT when added; DRAFT → OPEN → SETTLED, and DRAFT or OPEN → VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/** A move of a claim's status: open, settle or void. */
export type ClaimAction = 'open' | 'settle' | 'void';

export interface ClaimView {
  id: number;
  personId: number;
  /** The amount with two decimals, e.g. "10.25". */
  amount: string;
  /** yyyy-mm-dd */
  date: string;
  note: string;
  status: ClaimStatus;
  /** The sheet's number given when the claim was opened; null while DRAFT and once VOID. */
  number: number | null;
  /**
   * The due fixed when the claim was settled, with two decimals; null when it is not fixed (not
   * settled, or the grade had no rate then), so its due follows the current rate.
   */
  settledDue: string | null;
  /** The user who opened the claim; null until it is opened. The opener cannot settle it. */
  openedBy: string | null;
  /** Whether the claim is bound by its person's last statement to the figure it had then. */
  stated: boolean;
  /** The figure the statement bound the claim to, with two decimals; null when unbound, or when it was n/a. */
  statedDue: string | null;
}

/** Whether a claim counts toward what is claimed and due: only OPEN and SETTLED claims do. */
export function counts(claim: ClaimView): boolean {
  return claim.status === 'OPEN' || claim.status === 'SETTLED';
}

export interface ClaimForm {
  amount: string;
  /** Empty means the sheet's today (or, on an edit, the claim's own date). */
  date: string | null;
  note: string;
}

/** An amount as a claim takes it: 0.00 or more, with up to two decimals. */
export const AMOUNT = /^\d{1,12}(\.\d{1,2})?$/;

/** A two-decimal amount in whole cents, so sums are exact. */
export function cents(amount: string): number {
  const [whole, frac = ''] = amount.split('.');
  return Number(whole) * 100 + Number(frac.padEnd(2, '0'));
}

/** Whole cents shown with two decimals. */
export function money(cents: number): string {
  return `${Math.trunc(cents / 100)}.${String(cents % 100).padStart(2, '0')}`;
}

// The claims people on a sheet make, read from and written to the store.
@Injectable({ providedIn: 'root' })
export class ClaimsApi {
  private readonly http = inject(HttpClient);

  /** The sheet's claims, newest first. */
  list(sheet: string): Promise<ClaimView[]> {
    return firstValueFrom(this.http.get<ClaimView[]>(`${this.url(sheet)}/claims`));
  }

  add(sheet: string, personId: number, form: ClaimForm): Promise<ClaimView> {
    return firstValueFrom(this.http.post<ClaimView>(`${this.url(sheet)}/people/${personId}/claims`, form));
  }

  edit(sheet: string, id: number, form: ClaimForm): Promise<ClaimView> {
    return firstValueFrom(this.http.put<ClaimView>(`${this.url(sheet)}/claims/${id}`, form));
  }

  /**
   * Move a claim's status; refused (409) when its status does not allow the move,
   * or when the user settling it is the one who opened it.
   */
  act(sheet: string, id: number, action: ClaimAction): Promise<ClaimView> {
    return firstValueFrom(this.http.post<ClaimView>(`${this.url(sheet)}/claims/${id}/${action}`, null));
  }

  private url(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}`;
  }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: what each person has claimed and their due-total,
 * and the sheet's claimed-total and due-total. A change takes them before it writes and has them
 * audited after its own records, so every figure it moves is recorded.
 */
@Service
public class Rollups {

    /** Shown in place of a due-total when the grade has no rate. */
    private static final String NO_RATE = "n/a";

    /** A person's figures: what they have claimed and their due-total (null when n/a). */
    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal) {

        boolean sameAs(Figures other) {
            return other != null && same(claimed, other.claimed) && same(dueTotal, other.dueTotal);
        }
    }

    /** The sheet's figures: each person's by id, in the order they were added, and the sheet's totals. */
    public record Rollup(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Dues dues;
    private final Audit audit;

    public Rollups(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            Dues dues, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.dues = dues;
        this.audit = audit;
    }

    /** The sheet's figures as they stand now in the current transaction. */
    public Rollup take(String sheetId) {
        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
        Map<Long, List<Claim>> byPerson = new LinkedHashMap<>();
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            if (claim.getStatus().counts()) {
                byPerson.computeIfAbsent(claim.getPersonId(), id -> new ArrayList<>()).add(claim);
            }
        }
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = zero();
        BigDecimal dueTotal = zero();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            List<Claim> counting = byPerson.getOrDefault(person.getId(), List.of());
            BigDecimal claimed = zero();
            BigDecimal due = zero();
            boolean fixed = false;
            for (Claim claim : counting) {
                claimed = claimed.add(claim.getAmount());
                BigDecimal figure = dues.figure(claim, person.getGrade());
                if (figure != null) {
                    due = due.add(figure);
                }
                fixed |= claim.getSettledDue() != null || (claim.isStated() && claim.getStatedDue() != null);
            }
            // As on the screen: n/a when the grade has no rate today, unless a claim keeps a fixed figure.
            boolean rated = today != null && rates.findInForce(sheetId, person.getGrade(), today).isPresent();
            if (!rated && !fixed) {
                due = null;
            }
            figures.put(person.getId(), new Figures(person.getName(), claimed, due));
            claimedTotal = claimedTotal.add(claimed);
            if (due != null) {
                dueTotal = dueTotal.add(due);
            }
        }
        return new Rollup(figures, claimedTotal, dueTotal);
    }

    /**
     * Record, once the change commits, one ROLLUP line per person whose figures moved since
     * {@code before} (a person new since then counts as moved), then a TOTALS line when the sheet's
     * totals moved.
     */
    public void audit(String sheetId, String user, Rollup before) {
        Rollup after = take(sheetId);
        after.people().forEach((id, figures) -> {
            if (!figures.sameAs(before.people().get(id))) {
                audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + figures.name()
                        + " claimed=" + figures.claimed().toPlainString() + " due-total=" + shown(figures.dueTotal()));
            }
        });
        if (!same(after.claimedTotal(), before.claimedTotal()) || !same(after.dueTotal(), before.dueTotal())) {
            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user
                    + " claimed-total=" + after.claimedTotal().toPlainString()
                    + " due-total=" + after.dueTotal().toPlainString());
        }
    }

    /** Whether two figures are the same amount, or both n/a. */
    private static boolean same(BigDecimal a, BigDecimal b) {
        return a == null ? b == null : b != null && a.compareTo(b) == 0;
    }

    private static String shown(BigDecimal due) {
        return due != null ? due.toPlainString() : NO_RATE;
    }

    private static BigDecimal zero() {
        return BigDecimal.ZERO.setScale(2);
    }
}
